// fields.mjs
// Reimplementation of the whoosh.fields interface (black-box, behavior-aligned).
// Only the observable behavior used by the source script is modeled:
// constructing a Schema with typed fields and printing it.

export class FieldType {
  constructor({ stored = false } = {}) {
    this.stored = stored;
  }
}

export class ID extends FieldType {}
export class TEXT extends FieldType {}
export class KEYWORD extends FieldType {}
export class NUMERIC extends FieldType {}

// Python-style repr for a string: wrapped in single quotes.
function pyReprString(s) {
  return `'${s}'`;
}

export class Schema {
  // Mirrors whoosh.fields.Schema(**fields): field names come from kwargs.
  constructor(fields = {}) {
    this._fields = { ...fields };
  }

  names() {
    // whoosh's Schema.names() returns the sorted field names.
    return Object.keys(this._fields).sort();
  }

  // Mirrors Schema.__repr__: "<Schema: ['name1', 'name2', ...]>"
  toString() {
    const inner = this.names().map(pyReprString).join(', ');
    return `<Schema: [${inner}]>`;
  }
}

