// argparser.mjs
// Minimal black-box reimplementation of the argparse behavior used by the
// source script: one required string option --a, plus the implicit -h/--help.
// Error/help formatting mirrors Python's argparse output character for
// character, including exit codes (0 for --help, 2 for usage errors).

import { basename } from 'node:path';

function progName() {
  // argparse uses os.path.basename(sys.argv[0]); the Node equivalent of
  // sys.argv[0] here is the script path, process.argv[1].
  return basename(process.argv[1] || 'test2.mjs');
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A`;
}

function printHelpAndExit(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
  ];
  console.log(lines.join('\n'));
  process.exit(0);
}

function errorAndExit(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// Parses process.argv (skipping node + script path) like:
//   parser.add_argument('--a', type=str, required=True)
export function parseArgs(argv = process.argv.slice(2)) {
  const prog = progName();
  const result = { a: undefined };
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelpAndExit(prog);
    } else if (token === '--a') {
      const value = argv[i + 1];
      if (value === undefined) {
        errorAndExit(prog, 'argument --a: expected one argument');
      }
      result.a = value; // type=str: keep the raw string
      i++;
    } else if (token.startsWith('--a=')) {
      result.a = token.slice('--a='.length);
    } else {
      extras.push(token);
    }
  }

  if (result.a === undefined) {
    errorAndExit(prog, 'the following arguments are required: --a');
  }
  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return result;
}

