// test2.mjs
// Entry file — mirrors /workspace/dataset/test2.py:
//   import argparse
//   from whoosh.fields import Schema, TEXT, ID, KEYWORD, NUMERIC
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
//   args = parser.parse_args()
//   schema = Schema(id=ID(stored=True), title=TEXT(stored=True), tags=KEYWORD, price=NUMERIC(stored=True))
//   print(schema)

import { parseArgs } from './argparser.mjs';
import { Schema, TEXT, ID, KEYWORD, NUMERIC } from './fields.mjs';

const args = parseArgs();
void args; // parsed for argument-validation parity with the Python script

// Create schema with multiple field types.
// `tags=KEYWORD` in Python passes the class itself; mirrored here as the class.
const schema = new Schema({
  id: new ID({ stored: true }),
  title: new TEXT({ stored: true }),
  tags: KEYWORD,
  price: new NUMERIC({ stored: true }),
});

console.log(schema.toString());

